import { NODES } from "./trailerNodes";

export const NODE_BY_ID = NODES;

// meshName -> nodeId
export const MESH_TO_NODE = Object.fromEntries(
  Object.values(NODES).flatMap((node) => [
    ...(node.meshes || []).map((m) => [m.name, node.id]),
    ...(node.roots || []).map((r) => [r, node.id]),
  ])
);


// Parent label -> nodeId (optional)
export const PARENT_TO_NODE = Object.fromEntries(
  Object.values(NODES).map((node) => [node.Parent, node.id])
);

// ✅ rootName -> nodeId  (THIS is what your App.js expects)
export const ROOT_TO_NODE = Object.fromEntries(
  Object.values(NODES).flatMap((node) =>
    (node.roots || []).map((rootName) => [rootName, node.id])
  )
);
