// src/config/components/ConstInfoPanel.jsx
import React, { useEffect, useMemo, useRef, useState } from "react";
import { Box, Typography, Slider, Switch, FormControlLabel, Divider } from "@mui/material";
import * as THREE from "three";
// src/config/components/ConstInfoPanel.jsx


const _v = new THREE.Vector3();
const _box = new THREE.Box3();

function getMesh(scene, name) {
  return scene?.getObjectByName(name) || null;
}

function getWorldX(obj) {
  obj.getWorldPosition(_v);
  return _v.x;
}
function setWorldX(obj, worldX) {
  obj.getWorldPosition(_v);
  _v.x = worldX;
  if (obj.parent) {
    obj.parent.worldToLocal(_v);
    obj.position.x = _v.x;
  } else {
    obj.position.x = worldX;
  }
}

function getWorldY(obj) {
  obj.getWorldPosition(_v);
  return _v.y;
}
function setWorldY(obj, worldY) {
  obj.getWorldPosition(_v);
  _v.y = worldY;
  if (obj.parent) {
    obj.parent.worldToLocal(_v);
    obj.position.y = _v.y;
  } else {
    obj.position.y = worldY;
  }
}

function getWorldZ(obj) {
  obj.getWorldPosition(_v);
  return _v.z;
}
function setWorldZ(obj, worldZ) {
  obj.getWorldPosition(_v);
  _v.z = worldZ;
  if (obj.parent) {
    obj.parent.worldToLocal(_v);
    obj.position.z = _v.z;
  } else {
    obj.position.z = worldZ;
  }
}

function getWorldBoundsX(obj) {
  obj.updateWorldMatrix(true, true);
  _box.setFromObject(obj);
  return {
    minX: _box.min.x,
    maxX: _box.max.x,
    lenX: _box.max.x - _box.min.x,
  };
}

function clamp(v, min, max) {
  return Math.max(min, Math.min(max, v));
}


function setVisible(scene, names, visible) {
  for (const n of names || []) {
    const obj = getMesh(scene, n);
    if (!obj) continue;

    obj.visible = !!visible;

    if (obj.isMesh || obj.isSkinnedMesh) {
      obj.raycast = visible ? THREE.Mesh.prototype.raycast : () => null;
    }
  }
}

/**
 * Pivot-proof stretch to match a target span length.
 */
function stretchToSpanX(scene, meshName, baseSnap, targetLeftX, targetRightX, anchorEdge) {
  const m = getMesh(scene, meshName);
  if (!m) return;

  const base = baseSnap.mesh?.[meshName];
  if (!base) return;

  const targetLen = targetRightX - targetLeftX;
  if (targetLen <= 0) return;

  const factor = base.baseLenX > 0 ? targetLen / base.baseLenX : 1;
  m.scale.x = base.baseScaleX * factor;

  const b = getWorldBoundsX(m);

  if (anchorEdge === "right") {
    const delta = targetRightX - b.maxX;
    setWorldX(m, getWorldX(m) + delta);
  } else {
    const delta = targetLeftX - b.minX;
    setWorldX(m, getWorldX(m) + delta);
  }
}

/**
 * Followers maintain base offsets to a chosen reference.
 */
function moveFollowers(scene, followerNames, baseSnap, refKey, newRefX) {
  for (const name of followerNames || []) {
    const m = getMesh(scene, name);
    if (!m) continue;

    const f = baseSnap.followers?.[name];
    const off = f?.offsetByRef?.[refKey];
    if (off == null) continue;

    setWorldX(m, newRefX + off);
  }
}

function Row({ label, value }) {
  return (
    <Box sx={{ display: "flex", justifyContent: "space-between", gap: 1, mb: 0.25, opacity: 0.9 }}>
      <Typography sx={{ fontSize: 12, opacity: 0.75 }}>{label}</Typography>
      <Typography sx={{ fontSize: 12, fontWeight: 600 }}>{String(value ?? "-")}</Typography>
    </Box>
  );
}

function snapBBoxEdgeX(scene, meshName, targetX, edge) {
  const m = getMesh(scene, meshName);
  if (!m) return;

  const b = getWorldBoundsX(m);
  const current = edge === "right" ? b.maxX : b.minX;
  const delta = targetX - current;
  setWorldX(m, getWorldX(m) + delta);
}

export default function ConstInfoPanel({ scene, groupId, CONST_INFO }) {
  const def = CONST_INFO?.[groupId] || null;
  const sys = def?.system || null;
  const ui = def?.ui?.Customization || [];

  const hasSplit = !!sys?.anchors && !!sys?.spans && typeof sys?.defaults?.top1_cm === "number";
  const parentCm = Number(sys?.defaults?.parent_cm ?? 200);

  const toggles = useMemo(() => ui.filter((c) => c.type === "toggle"), [ui]);

  const splitSlider = useMemo(() => {
    if (!hasSplit) return null;
    return ui.find((c) => c.type === "slider" && c.key === "split_top1_cm");
  }, [ui, hasSplit]);

  const sliders = useMemo(() => ui.filter((c) => c.type === "slider"), [ui]);

  // move sliders (x/y/z)
  const moveSliders = useMemo(() => sliders.filter((c) => c.move?.axis), [sliders]);
  // rotate sliders (x/y/z)

// -------------------------
// GROUPED UI (uses c.group)
// -------------------------
const groupedUI = useMemo(() => {
  const map = {};
  for (const c of ui) {
    const g = c.group || "Other";
    if (!map[g]) map[g] = [];
    map[g].push(c);
  }
  return map;
}, [ui]);

const groupOrder = [
  "Top 1",
  "Top 2",
  "Lower shelf under Top 1",
  "Lower shelf under Top 2",
  "Grommet on Top 1",
  "Grommet on Top 2",
"Left leg",
"Middle leg",
"Right leg",
  "Other",
];

const groupToggleKey = (groupName) => {
  const map = {
    "Top 1": "top1",
    "Top 2": "top2",
    "Lower shelf under Top 1": "lower1",
    "Lower shelf under Top 2": "lower2",
    "Grommet on Top 1": "grommet_top1",
    "Grommet on Top 2": "grommet_top2",
"Left leg": "left_leg",
"Middle leg": "middle_leg",
"Right leg": "right_leg",
  };
  return map[groupName] ?? null;
};

const isGroupEnabled = (groupName) => {
  const tKey = groupToggleKey(groupName);
  if (!tKey) return true;
  return Boolean(state?.[tKey]);
};

const resolveLabel = (c) => {
  const value = Number(state?.[c.key] ?? c.defaultValue ?? 0);

  const out =
    typeof c.label === "function"
      ? c.label({ value, state, c })
      : c.label;

  return String(out ?? "");
};


function renderControl(c) {
  if (c.type === "toggle") {
    return (
      <Box key={c.key} sx={{ mb: 0.5 }}>
        <FormControlLabel
          sx={{ m: 0 }}
          control={
            <Switch
              checked={Boolean(state[c.key])}
              onChange={(e) => setValue(c.key, e.target.checked)}
            />
          }
         label={
  <Typography sx={{ fontSize: 12, whiteSpace: "pre-line" }}>
    {resolveLabel(c)}
  </Typography>
}

        />
      </Box>
    );
  }

if (c.type === "text") {
  return (
    <Box key={c.key} sx={{ mb: 1 }}>
      <Typography sx={{ fontSize: 12, opacity: 0.8, whiteSpace: "pre-line" }}>
        {resolveLabel(c)}
      </Typography>
    </Box>
  );
}


  if (c.type === "slider") {
    // ignore split slider if this group doesn't support split
    if (c.key === "split_top1_cm" && !(hasSplit && splitSlider)) return null;

    return (
      <Box key={c.key} sx={{ mb: 1.25 }}>
      <Typography sx={{ fontSize: 12, mb: 0.5, whiteSpace: "pre-line" }}>
  {resolveLabel(c)}
</Typography>

        <Slider
          value={Number(state[c.key] ?? c.defaultValue ?? 0)}
          min={Number(c.min)}
          max={Number(c.max)}
          step={Number(c.step)}
          onChange={(_, v) => setValue(c.key, Number(v))}
        />
      </Box>
    );
  }

  return null;
}



  // ✅ per-group memory (do not reset to default unless Reset)
  const stateByGroupRef = useRef({}); // { [groupId]: state }

  const initialState = useMemo(() => {
const s = {
  width_cm: Number(sys?.defaults?.parent_cm ?? 200),
  split_top1_cm: Number(splitSlider?.defaultValue ?? sys?.defaults?.top1_cm ?? 74),
};

s.top2_width_cm = Number(sys?.defaults?.top2_cm ?? (parentCm - s.split_top1_cm));


    for (const c of sliders) {
      if (c.key === "split_top1_cm") continue;
      if (c.key === "width_cm") continue;
      s[c.key] = Number(c.defaultValue ?? 0);
    }



    for (const c of toggles) s[c.key] = Boolean(c.defaultValue);
    return s;
  }, [splitSlider, sliders, toggles, sys]);

  const [state, setState] = useState(initialState);

  const armedRef = useRef(false);
  const baseRef = useRef(null);

function applyToggles(s) {
  if (!scene || !sys) return;

  // enforce: if top is off -> grommet must be off
  const next = { ...s };
  if (next.top1 === false) next.grommet_top1 = false;
  if (next.top2 === false) next.grommet_top2 = false;

  for (const [k, t] of Object.entries(sys.toggles || {})) {
    setVisible(scene, t.meshes, Boolean(next[k]));
  }
}




function captureStretchBase(preset) {
  if (!scene || !preset?.anchors) return null;

  const leftA = getMesh(scene, preset.anchors.left);
  const rightA = getMesh(scene, preset.anchors.right);
  if (!leftA || !rightA) return null;

  scene.updateMatrixWorld(true);

  const leftInnerX = getWorldX(leftA);
  const rightInnerX = getWorldX(rightA);

  const snap = {
    leftInnerX,
    baseLen: rightInnerX - leftInnerX,
    meshSnap: {},
    rigidLeftSnap: {},
    rigidRightSnap: {},
  };

  // stretch meshes
  for (const name of [
    ...(preset.spans?.leftSpan?.stretch || []),
    ...(preset.spans?.rightSpan?.stretch || []),
  ]) {
    const m = getMesh(scene, name);
    if (!m) continue;
    const b = getWorldBoundsX(m);
    snap.meshSnap[name] = { baseLenX: b.lenX, baseScaleX: m.scale.x };
  }

  // rigid LEFT
  for (const name of preset.rigid?.left || []) {
    const m = getMesh(scene, name);
    if (!m) continue;
    snap.rigidLeftSnap[name] = getWorldX(m) - leftInnerX;
  }

  // rigid RIGHT
  for (const name of preset.rigid?.right || []) {
    const m = getMesh(scene, name);
    if (!m) continue;
    snap.rigidRightSnap[name] = getWorldX(m) - rightInnerX;
  }

  return snap;
}

  // Fallback base capture for move/rotate sliders (works even when group has NO anchors)
  function captureMoveBaseOnly() {
    if (!scene) return null;

    scene.updateMatrixWorld(true);

const snap = { moveBase: {} };


    // capture positions for any meshes referenced by move sliders
    for (const sl of moveSliders) {
      for (const name of sl.move?.meshes || []) {
        const m = getMesh(scene, name);
        if (!m) continue;

      if (!snap.moveBase[name]) {
        m.getWorldPosition(_v);
        snap.moveBase[name] = { x: _v.x, y: _v.y, z: _v.z };
      }
    }
  }

  return snap;
}

  function captureBase() {
    if (!scene || !sys) return null;

    const leftA = getMesh(scene, sys.anchors?.left);
    const midA = getMesh(scene, sys.anchors?.middle);
    const rightA = getMesh(scene, sys.anchors?.right);
    if (!leftA || !midA || !rightA) return null;

    const baseLeftX = getWorldX(leftA);
    const baseMidX = getWorldX(midA);
    const baseRightX = getWorldX(rightA);

    const leftBounds = getWorldBoundsX(leftA);
    const rightBounds = getWorldBoundsX(rightA);
    const baseLeftInnerX = leftBounds.maxX;
    const baseRightInnerX = rightBounds.minX;

    const snap = {
      anchors: { baseLeftX, baseMidX, baseRightX },
      inner: { baseLeftInnerX, baseRightInnerX },
      baseParentLen: baseRightInnerX - baseLeftInnerX,
      mesh: {},
      followers: {},
      fixed: {},
      moveBase: {}, // base world positions
      rotBase: {}, // base local rotations
    };

    const wb43 = getMesh(scene, "WorkBench_43");
    snap.fixed.wb43WorldX = wb43 ? getWorldX(wb43) : null;

    const baseLeftSpanLeft = baseLeftInnerX;
    const baseLeftSpanRight = baseMidX;
    const baseRightSpanLeft = baseMidX;
    const baseRightSpanRight = baseRightInnerX;

    const baseLeftSpanCenter = (baseLeftSpanLeft + baseLeftSpanRight) / 2;
    const baseRightSpanCenter = (baseRightSpanLeft + baseRightSpanRight) / 2;

    const allStretch = [
      ...(sys.spans?.leftSpan?.stretch || []),
      ...(sys.spans?.rightSpan?.stretch || []),
    ];

    for (const name of allStretch) {
      const m = getMesh(scene, name);
      if (!m) continue;
      const b = getWorldBoundsX(m);
      snap.mesh[name] = { baseLenX: b.lenX, baseScaleX: m.scale.x };
    }

    const registerOffsets = (names, refs) => {
      for (const name of names || []) {
        const m = getMesh(scene, name);
        if (!m) continue;

        const wx = getWorldX(m);
        if (!snap.followers[name]) snap.followers[name] = { offsetByRef: {} };

        for (const [refKey, refX] of Object.entries(refs)) {
          snap.followers[name].offsetByRef[refKey] = wx - refX;
        }
      }
    };

    registerOffsets(sys.spans?.leftSpan?.followLeftEdge, {
      leftEdge: baseLeftSpanLeft,
      rightEdge: baseLeftSpanRight,
      center: baseLeftSpanCenter,
    });
    registerOffsets(sys.spans?.leftSpan?.followRightEdge, {
      leftEdge: baseLeftSpanLeft,
      rightEdge: baseLeftSpanRight,
      center: baseLeftSpanCenter,
    });
    registerOffsets(sys.spans?.leftSpan?.followCenter, {
      leftEdge: baseLeftSpanLeft,
      rightEdge: baseLeftSpanRight,
      center: baseLeftSpanCenter,
    });

    registerOffsets(sys.spans?.rightSpan?.followLeftEdge, {
      leftEdge: baseRightSpanLeft,
      rightEdge: baseRightSpanRight,
      center: baseRightSpanCenter,
    });
    registerOffsets(sys.spans?.rightSpan?.followRightEdge, {
      leftEdge: baseRightSpanLeft,
      rightEdge: baseRightSpanRight,
      center: baseRightSpanCenter,
    });
    registerOffsets(sys.spans?.rightSpan?.followCenter, {
      leftEdge: baseRightSpanLeft,
      rightEdge: baseRightSpanRight,
      center: baseRightSpanCenter,
    });

    registerOffsets(sys.rigid?.middle, { anchor: baseMidX });

    // base positions + base rotations for move/rotate sliders
    scene.updateMatrixWorld(true);

    for (const sl of moveSliders) {
      for (const name of sl.move?.meshes || []) {
        const m = getMesh(scene, name);
        if (!m) continue;

        if (!snap.moveBase[name]) {
          m.getWorldPosition(_v);
          snap.moveBase[name] = { x: _v.x, y: _v.y, z: _v.z };
        }
        if (!snap.rotBase[name]) {
          snap.rotBase[name] = { x: m.rotation.x, y: m.rotation.y, z: m.rotation.z };
        }
      }
    }

    return snap;
  }

  function applySplit(s) {
    if (!hasSplit) return;
    if (!scene || !sys) return;
    if (!armedRef.current) return;

    // must be full base with anchors/inner
    if (!baseRef.current || !baseRef.current.inner) {
      baseRef.current = captureBase();
    }
    const base = baseRef.current;
    if (!base?.inner) return;

    scene.updateMatrixWorld(true);

    const leftX = base.inner.baseLeftInnerX;
    const rightX = base.inner.baseRightInnerX;

    const wCm = Number(s.width_cm ?? parentCm);
    const top1Cm = clamp(Number(s.split_top1_cm), 1, wCm - 1);
    const unitsPerCm = base.baseParentLen / wCm;

    const midX = leftX + top1Cm * unitsPerCm;

    moveFollowers(scene, sys.rigid?.middle, base, "anchor", midX);

    scene.updateMatrixWorld(true);

    const trimL = getMesh(scene, "WorkBench_43");
    const trimR = getMesh(scene, "WorkBench_15");
    if (trimL && trimR) {
      const bL = getWorldBoundsX(trimL);
      const bR = getWorldBoundsX(trimR);

      const top1LeftX = bL.maxX;
      const top1RightX = bR.minX;

      stretchToSpanX(scene, "WorkBench_07", base, top1LeftX, top1RightX, "left");
      snapBBoxEdgeX(scene, "WorkBench_07", top1LeftX, "left");
      snapBBoxEdgeX(scene, "WorkBench_07", top1RightX, "right");
    }

    const leftSpanLeft = leftX;
    const leftSpanRight = midX;
    const rightSpanLeft = midX;
    const rightSpanRight = rightX;

    for (const name of sys.spans?.leftSpan?.stretch || []) {
      if (name === "WorkBench_07") continue;
      stretchToSpanX(scene, name, base, leftSpanLeft, leftSpanRight, "left");
    }

    for (const name of sys.spans?.rightSpan?.stretch || []) {
      stretchToSpanX(scene, name, base, rightSpanLeft, rightSpanRight, "right");
    }

    for (const name of sys.spans?.leftSpan?.followLeftEdge || []) {
      if (name === "WorkBench_43") continue;
      snapBBoxEdgeX(scene, name, leftSpanLeft, "left");
    }
    for (const name of sys.spans?.leftSpan?.followRightEdge || []) {
      if (name === "WorkBench_15") continue;
      snapBBoxEdgeX(scene, name, leftSpanRight, "right");
    }

    for (const name of sys.spans?.rightSpan?.followLeftEdge || []) {
      snapBBoxEdgeX(scene, name, rightSpanLeft, "left");
    }
    for (const name of sys.spans?.rightSpan?.followRightEdge || []) {
      snapBBoxEdgeX(scene, name, rightSpanRight, "right");
    }

    const leftCenter = (leftSpanLeft + leftSpanRight) / 2;
    const rightCenter = (rightSpanLeft + rightSpanRight) / 2;

    moveFollowers(scene, sys.spans?.leftSpan?.followCenter, base, "center", leftCenter);
    moveFollowers(scene, sys.spans?.rightSpan?.followCenter, base, "center", rightCenter);
  }

function applyStretch(s) {
  if (!scene || !sys) return;
  if (!sys?.anchors?.left || !sys?.anchors?.right) return;

  const baseCm = Number(sys?.defaults?.parent_cm ?? 0);
  const newCm = Number(s.width_cm ?? baseCm);
  if (!baseCm || !Number.isFinite(newCm)) return;

  const factor = newCm / baseCm;
  if (!Number.isFinite(factor) || factor <= 0) return;

  if (!baseRef.current) baseRef.current = {};
  if (!baseRef.current.stretchBase) {
    scene.updateMatrixWorld(true);

    const leftA = getMesh(scene, sys.anchors.left);
    const rightA = getMesh(scene, sys.anchors.right);
    if (!leftA || !rightA) return;

    const leftInnerX = getWorldX(leftA);
    const rightInnerX = getWorldX(rightA);

    const baseLen = rightInnerX - leftInnerX;
    if (baseLen <= 0) return;

    const allStretchMeshes = [
      ...(sys.spans?.leftSpan?.stretch || []),
      ...(sys.spans?.rightSpan?.stretch || []),
    ];

    const meshSnap = {};
    for (const name of allStretchMeshes) {
      const m = getMesh(scene, name);
      if (!m) continue;
      const b = getWorldBoundsX(m);
      meshSnap[name] = { baseLenX: b.lenX, baseScaleX: m.scale.x };
    }

    // ✅ capture rigid LEFT offsets from left edge
    const rigidLeftSnap = {};
    for (const name of sys.rigid?.left || []) {
      const m = getMesh(scene, name);
      if (!m) continue;
      rigidLeftSnap[name] = getWorldX(m) - leftInnerX;
    }

    // existing rigid RIGHT offsets
    const rigidRightSnap = {};
    for (const name of sys.rigid?.right || []) {
      const m = getMesh(scene, name);
      if (!m) continue;
      rigidRightSnap[name] = getWorldX(m) - rightInnerX;
    }

    baseRef.current.stretchBase = {
      leftInnerX,
      baseLen,
      meshSnap,
      rigidLeftSnap,   // ✅ add
      rigidRightSnap,
    };
  }

  const sb = baseRef.current.stretchBase;
  if (!sb) return;

  scene.updateMatrixWorld(true);

  const targetLeftX = sb.leftInnerX;
  const targetRightX = sb.leftInnerX + sb.baseLen * factor;

  const allStretchMeshes = [
    ...(sys.spans?.leftSpan?.stretch || []),
    ...(sys.spans?.rightSpan?.stretch || []),
  ];

  // stretch meshes scale to match new span
  for (const name of allStretchMeshes) {
    stretchToSpanX(scene, name, { mesh: sb.meshSnap }, targetLeftX, targetRightX, "left");
  }

  // ✅ move rigid LEFT parts relative to left edge
  for (const name of sys.rigid?.left || []) {
    const m = getMesh(scene, name);
    const off = sb.rigidLeftSnap?.[name];
    if (!m || off == null) continue;
    setWorldX(m, targetLeftX + off);
  }

  // existing rigid RIGHT
  for (const name of sys.rigid?.right || []) {
    const m = getMesh(scene, name);
    const off = sb.rigidRightSnap?.[name];
    if (!m || off == null) continue;
    setWorldX(m, targetRightX + off);
  }
}


  // ✅ move meshes for sliders with move.axis = "x" | "y" | "z"
  function applyMoveAxes(s) {
    if (!scene) return;

    if (!baseRef.current) baseRef.current = captureBase();
    if (!baseRef.current || !baseRef.current.moveBase) {
      baseRef.current = captureMoveBaseOnly();
    }

    const base = baseRef.current;
    if (!base?.moveBase) return;

    scene.updateMatrixWorld(true);

    for (const sl of moveSliders) {
      const axis = sl.move.axis; // "x" | "y" | "z"
      const d = Number(s[sl.key] ?? 0);

      for (const name of sl.move.meshes || []) {
        const m = getMesh(scene, name);
        const bp = base.moveBase?.[name];
        if (!m || !bp) continue;

        if (axis === "x") setWorldX(m, bp.x + d);
        if (axis === "y") setWorldY(m, bp.y + d);
        if (axis === "z") setWorldZ(m, bp.z + d);
      }
    }
  }

  // ✅ rotate meshes for sliders with rotate.axis = "x" | "y" | "z"


  // ✅ restore saved state per groupId; do NOT reset to defaults automatically
  useEffect(() => {
    armedRef.current = false;
    baseRef.current = null;

    const saved = stateByGroupRef.current[groupId];
    const nextState = saved ?? initialState;

    setState(nextState);

    if (!scene || !sys) return;

    for (const [k, t] of Object.entries(sys.toggles || {})) {
      setVisible(scene, t.meshes, Boolean(nextState[k]));
    }

    applyMoveAxes(nextState);

}, [groupId, scene, sys, initialState]);

  const setValue = (key, value) => {
    setState((prev) => {
const next = { ...prev, [key]: value };

// keep split + Top2 width in sync
if (hasSplit) {
  if (key === "top2_width_cm") {
    const top2 = clamp(Number(value), 1, parentCm - 1);
    next.top2_width_cm = top2;
    next.split_top1_cm = parentCm - top2; // <-- THIS drives the real split
  }

  if (key === "split_top1_cm") {
    const top1 = clamp(Number(value), 1, parentCm - 1);
    next.split_top1_cm = top1;
    next.top2_width_cm = parentCm - top1;
  }
}

      applyToggles(next);
if (next.top1 === false && next.grommet_top1 !== false) next.grommet_top1 = false;
if (next.top2 === false && next.grommet_top2 !== false) next.grommet_top2 = false;


      // arm on ANY slider move (split or move/rotate)
      const isSlider = sliders.some((c) => c.key === key);
    if (isSlider && !armedRef.current) {
  armedRef.current = true;

  // keep other snapshots, but force stretch to recapture
  if (!baseRef.current) baseRef.current = {};
  delete baseRef.current.stretchBase;
}

      if (hasSplit) applySplit(next);

      applyMoveAxes(next);


      stateByGroupRef.current[groupId] = next;
      return next;
    });
  };

  if (!def || !sys) {
    return (
      <Typography sx={{ fontSize: 12, opacity: 0.75 }}>
        No CONST_INFO.system found for {groupId}
      </Typography>
    );
  }

  const top1 = hasSplit ? Number(state.split_top1_cm) : null;
  const top2 = hasSplit ? parentCm - top1 : null;

  return (
    <Box sx={{ fontSize: 12 }}>
      <Typography sx={{ fontSize: 13, fontWeight: 700, mb: 1 }}>{def.label}</Typography>

      {!!def?.info && (
        <Box sx={{ mb: 1 }}>
          {Object.entries(def.info).map(([k, v]) => (
            <Row key={k} label={k.replace(/_/g, " ")} value={v} />
          ))}
          <Divider sx={{ mt: 1, opacity: 0.2 }} />
        </Box>
      )}

<Divider sx={{ my: 1, opacity: 0.2 }} />


      {hasSplit && (
        <Box sx={{ mb: 1 }}>
          <Row label="Top 1 (cm)" value={top1} />
          <Row label="Top 2 (cm)" value={top2} />
          <Row label="Total (cm)" value={top1 + top2} />
          <Divider sx={{ mt: 1, opacity: 0.2 }} />
        </Box>
      )}


{groupOrder
  .filter((g) => groupedUI[g]?.length)
  .map((g) => {
    const items = groupedUI[g];

    const tKey = groupToggleKey(g);
    const groupToggle = tKey ? items.find((x) => x.type === "toggle" && x.key === tKey) : null;

    return (
      <Box key={g} sx={{ mb: 1.25 }}>
        {/* Always show the controlling toggle (if any) */}
        {groupToggle ? renderControl(groupToggle) : null}

        {/* Only show the rest (text + sliders) when enabled */}
        {isGroupEnabled(g) &&
          items
            .filter((x) => !(groupToggle && x.key === groupToggle.key))
            .map(renderControl)}

        <Divider sx={{ mt: 1, opacity: 0.15 }} />
      </Box>
    );
  })}

 

{sliders.some(s => s.key === "width_cm") && (
  <Box sx={{ mb: 1.5 }}>
    <Typography sx={{ fontSize: 12, mb: 0.5 }}>Width (cm)</Typography>
    <Slider
      value={Number(state.width_cm ?? parentCm)}
      min={Number(sliders.find(s => s.key === "width_cm")?.min ?? 50)}
      max={Number(sliders.find(s => s.key === "width_cm")?.max ?? 100)}
      step={Number(sliders.find(s => s.key === "width_cm")?.step ?? 1)}
      onChange={(_, v) => setValue("width_cm", Number(v))}
    />
  </Box>
)}


      <Typography
        sx={{ fontSize: 11, opacity: 0.7, mt: 1, cursor: "pointer", userSelect: "none" }}
onClick={() => {
  armedRef.current = false;

  if (!baseRef.current) baseRef.current = {};
  delete baseRef.current.stretchBase;

  delete stateByGroupRef.current[groupId];

  setState(initialState);
  if (scene) applyToggles(initialState);
  if (scene) applyMoveAxes(initialState);


}}

      >
        Reset (static until slider move)
      </Typography>
    </Box>
  );
}
