export function validateTrailerConfig({ scene, TRAILER_GROUPS, NODES, MESH_TO_GROUP }) {
  const glbNames = new Set()
  scene.traverse((o) => {
    if (o.name) glbNames.add(o.name)
  })

  const missingFromGlb = []
  for (const [group, meshes] of Object.entries(TRAILER_GROUPS)) {
    for (const name of meshes) {
      if (!glbNames.has(name)) missingFromGlb.push({ group, name })
    }
  }

  const badMeshToGroup = []
  for (const [group, meshes] of Object.entries(TRAILER_GROUPS)) {
    for (const name of meshes) {
      if (MESH_TO_GROUP[name] !== group) {
        badMeshToGroup.push({ group, name, got: MESH_TO_GROUP[name] })
      }
    }
  }

  const missingNodeMeshes = []
  const missingNodeRoots = []
  for (const node of Object.values(NODES)) {
    for (const m of node.meshes || []) {
      if (!glbNames.has(m.name)) missingNodeMeshes.push({ node: node.id, name: m.name })
    }
    for (const r of node.roots || []) {
      if (!glbNames.has(r)) missingNodeRoots.push({ node: node.id, root: r })
    }
  }

  console.group("Trailer Config Validation")
  console.log("GLB node count:", glbNames.size)
  console.log("Missing from GLB (TRAILER_GROUPS):", missingFromGlb.length, missingFromGlb.slice(0, 30))
  console.log("Bad MESH_TO_GROUP entries:", badMeshToGroup.length, badMeshToGroup.slice(0, 30))
  console.log("Missing node meshes:", missingNodeMeshes.length, missingNodeMeshes.slice(0, 30))
  console.log("Missing node roots:", missingNodeRoots.length, missingNodeRoots.slice(0, 30))
  console.groupEnd()

  return { missingFromGlb, badMeshToGroup, missingNodeMeshes, missingNodeRoots }
}
