import * as THREE from "three";

export function buildPresetDimensions({ scene, groupId, CONST_INFO }) {
  if (!scene || !groupId || !CONST_INFO?.[groupId]) return [];

  const sys = CONST_INFO[groupId]?.system;
  const parentCm = Number(sys?.defaults?.parent_cm);
  if (!Number.isFinite(parentCm) || parentCm <= 0) return [];

  // 1) Choose the axis in world space (assume trailer is axis-aligned)
  const axis =
    sys.axis === "z" ? new THREE.Vector3(0, 0, 1) : new THREE.Vector3(1, 0, 0);

  // 2) Build bbox ONLY from dimensionRoots
  const roots = Array.isArray(sys.dimensionRoots) ? sys.dimensionRoots : [];
  if (roots.length === 0) return [];

  const box = new THREE.Box3();
  let found = false;

  for (const name of roots) {
    const obj = scene.getObjectByName(name);
    if (!obj) continue;
    const b = new THREE.Box3().setFromObject(obj);
    if (!found) box.copy(b);
    else box.union(b);
    found = true;
  }

  if (!found) return [];

  // 3) Compute endpoints by projecting bbox corners onto axis
  const corners = [
    new THREE.Vector3(box.min.x, box.min.y, box.min.z),
    new THREE.Vector3(box.min.x, box.min.y, box.max.z),
    new THREE.Vector3(box.min.x, box.max.y, box.min.z),
    new THREE.Vector3(box.min.x, box.max.y, box.max.z),
    new THREE.Vector3(box.max.x, box.min.y, box.min.z),
    new THREE.Vector3(box.max.x, box.min.y, box.max.z),
    new THREE.Vector3(box.max.x, box.max.y, box.min.z),
    new THREE.Vector3(box.max.x, box.max.y, box.max.z),
  ];

  let minT = Infinity;
  let maxT = -Infinity;

  for (const c of corners) {
    const t = c.dot(axis);
    minT = Math.min(minT, t);
    maxT = Math.max(maxT, t);
  }

  // ---- SINGLE wall value used everywhere (no duplicates) ----
  const wall = sys?.wall || "E1";

  // 4) Force all dims per wall to share one Y row (row alignment)
  const center = box.getCenter(new THREE.Vector3());

  // tune these two numbers only (row heights)
  const ROW_Y_E1 = 1.2;
  const ROW_Y_E2 = 1.2;

  const y = wall === "E2" ? ROW_Y_E2 : ROW_Y_E1;
  const origin = new THREE.Vector3(center.x, y, center.z);

  // 5) Convert min/max back to world points along axis
  const originT = origin.dot(axis);
  const a = origin.clone().add(axis.clone().multiplyScalar(minT - originT));
  const b = origin.clone().add(axis.clone().multiplyScalar(maxT - originT));

 // 6) Put EVERYTHING on the wall onto one shared Z plane (true alignment)
const ROW_Z_E1 = 0.2; // pick/tune this until E1 row looks perfect
const ROW_Z_E2 = +0.5; // pick/tune this until E2 row looks perfect

const rowZ = wall === "E2" ? ROW_Z_E2 : ROW_Z_E1;

const a2 = a.clone();
const b2 = b.clone();

// snap both endpoints to the same Z plane
a2.z = rowZ;
b2.z = rowZ;

return [
  {
    id: `${groupId}-parent`,
    a: a2,
    b: b2,
    valueCm: parentCm,
  },

  ];
}
