const CameraRig = ({ view, moveMode, controlsRef, cameraMode }) => {
  const { camera, gl } = useThree();

  useEffect(() => {
    if (!controlsRef?.current) return;

    // In "center" mode we do NOT force overview camera transforms here.
    if (cameraMode === "center") return;

    const distance = 8;

    const positions = {
      front: [0, 2, -distance],
      back: [0, 2, distance],
      left: [distance, 2, 0],
      right: [-distance, 2, 0],
      up: [0, distance, 0],
      down: [0, -distance, 0],
    };

    const targetPosition = positions[view] || positions.front;
    camera.position.set(...targetPosition);

    if (view === "up") {
      camera.lookAt(0, 0, 0);
      camera.up.set(0, 0, -1);
    } else if (view === "down") {
      camera.lookAt(0, 0, 0);
      camera.up.set(0, 0, 1);
    } else {
      camera.lookAt(0, 1.2, 0);
      camera.up.set(0, 1, 0);
    }

    camera.updateProjectionMatrix();

    controlsRef.current.target.set(0, 1.2, 0);
    controlsRef.current.update();
  }, [view, cameraMode, camera, controlsRef]);

  const inside = cameraMode === "center";
  const EPS = 0.05;

  return (
    <OrbitControls
      ref={controlsRef}
      args={[camera, gl.domElement]}
      enableZoom={true}
      enableRotate={!moveMode}
      enablePan={!moveMode && !inside}
      enableDamping={true}
      dampingFactor={0.08}
      minDistance={inside ? EPS : 0.5}
      maxDistance={inside ? EPS : 50}
    />
  );
};


