function RenderControls({ controls, valueMap, onChange, groupId }) {
  if (!controls?.length) {
    return (
      <Typography sx={{ fontSize: 12, opacity: 0.75 }}>
        No controls for this panel.
      </Typography>
    );
  }

  return (
    <Box sx={{ display: "flex", flexDirection: "column", gap: 1.5 }}>
      {controls.map((c) => {
        const v = valueMap?.[c.key] ?? c.defaultValue;

        if (c.type === "toggle") {
          return (
            <FormControlLabel
              key={c.key}
              label={c.label}
              control={
                <Switch
                  checked={!!v}
                  onChange={(e) => onChange(groupId, c.key, e.target.checked)}
                />
              }
            />
          );
        }

        if (c.type === "slider") {
          return (
            <Box key={c.key}>
              <Typography sx={{ fontSize: 12, opacity: 0.85, mb: 0.5 }}>
                {c.label}: <b>{Number(v)}</b>
              </Typography>
              <Slider
                value={Number(v)}
                min={c.min}
                max={c.max}
                step={c.step}
                valueLabelDisplay="auto"
                onChange={(_, value) => onChange(groupId, c.key, value)}
              />
            </Box>
          );
        }

        if (c.type === "select") {
          return (
            <Box key={c.key}>
              <Typography sx={{ fontSize: 12, opacity: 0.85, mb: 0.5 }}>
                {c.label}
              </Typography>
              <Select
                size="small"
                value={v}
                onChange={(e) => onChange(groupId, c.key, e.target.value)}
                sx={{ width: "100%" }}
              >
                {c.options.map((opt) => (
                  <MenuItem key={opt} value={opt}>
                    {opt}
                  </MenuItem>
                ))}
              </Select>
            </Box>
          );
        }

        return null;
      })}
    </Box>
  );
}


