// 1) Visibility gate (only allow picking visible objects)
const isPickable = React.useCallback(
  (obj) => isEffectivelyVisible(obj),
  [/* depends only on isEffectivelyVisible */]
);

// 2) Transform snapshot helpers (keeps your undo / callbacks unchanged)
const captureTransform = React.useCallback((obj) => {
  return {
    pos: [obj.position.x, obj.position.y, obj.position.z],
    rot: [obj.rotation.x, obj.rotation.y, obj.rotation.z],
    scale: [obj.scale.x, obj.scale.y, obj.scale.z],
  };
}, []);

// (Optional) keep if you use it elsewhere; not required by move itself
const transformsEqual = (a, b, eps = 1e-6) => {
  if (!a || !b) return true;
  const near = (x, y) => Math.abs(x - y) <= eps;

  return (
    near(a.pos[0], b.pos[0]) && near(a.pos[1], b.pos[1]) && near(a.pos[2], b.pos[2]) &&
    near(a.rot[0], b.rot[0]) && near(a.rot[1], b.rot[1]) && near(a.rot[2], b.rot[2]) &&
    near(a.scale[0], b.scale[0]) && near(a.scale[1], b.scale[1]) && near(a.scale[2], b.scale[2])
  );
};

// 3) Decide what object name becomes the drag target
//    DRAG_MODE = "mesh"  => drag exactly what you click
//    DRAG_MODE = "root"  => drag the top-level child under scene (moves assemblies)
const DRAG_MODE = "root"; // change to "root" if preferred

// Placement should drag the exact mesh; normal move can drag root
// Placement = drag exact mesh
// Normal move = drag root under scene
const getDragTargetName = React.useCallback(
  (hit) => {
    if (!hit || !scene) return null;

    const placementMode = !!placementGroupId;

    if (placementMode) {
      return hit.name || null;
    }

    let o = hit;
    while (o?.parent && o.parent !== scene) o = o.parent;
    return o?.name || hit.name || null;
  },
  [scene, placementGroupId]
);



