const focusOnObject = React.useCallback((obj3D) => {
  const controls = controlsRef.current;
  if (!obj3D || !controls) return;

  const camera = controls.object;

  // 1) Compute bounds & center
  const box = new THREE.Box3().setFromObject(obj3D);
  const center = new THREE.Vector3();
  const size = new THREE.Vector3();
  box.getCenter(center);
  box.getSize(size);

  // 2) Compute a good distance based on object size + camera FOV
  const maxDim = Math.max(size.x, size.y, size.z);
  const fov = THREE.MathUtils.degToRad(camera.fov);
  const fitDist = (maxDim * 0.5) / Math.tan(fov * 0.5);

  // padding factor: increase if you want more space around object
  const dist = Math.max(2.0, fitDist * 1.35);

  // 3) Keep current viewing direction (no weird rotation jumps)
  const dir = new THREE.Vector3()
    .subVectors(camera.position, controls.target)
    .normalize();

  // 4) Set orbit pivot to object center
  controls.target.copy(center);

  // 5) Place camera along same direction at the computed distance
  camera.position.copy(center.clone().add(dir.multiplyScalar(dist)));

  camera.updateProjectionMatrix();
  controls.update();
}, []);

const resetToFrontOverview = React.useCallback(() => {
  const controls = controlsRef.current;
  if (!controls) return;

  const camera = controls.object;

  const distance = 8; // must match CameraRig

  // Front overview position
  camera.position.set(0, 2, -distance);

  // Orbit pivot = trailer center
  controls.target.set(0, 1.2, 0);

  camera.up.set(0, 1, 0);
  camera.lookAt(0, 1.2, 0);

  camera.updateProjectionMatrix();
  controls.update();
}, []);


