const setOverviewView = React.useCallback((view) => {
  const controls = controlsRef.current;
  if (!controls) return;

  const camera = controls.object;
  const distance = 8;

  const positions = {
    front: [0, 2, -distance],
    back:  [0, 2,  distance],
    left:  [ distance, 2, 0],
    right: [-distance, 2, 0],
    up:    [0, distance, 0],
    down:  [0, -distance, 0],
  };

  const pos = positions[view] || positions.front;
  camera.position.set(...pos);

  controls.target.set(0, 1.2, 0);

  if (view === "up") {
    camera.up.set(0, 0, -1);
    camera.lookAt(0, 0, 0);
  } else if (view === "down") {
    camera.up.set(0, 0, 1);
    camera.lookAt(0, 0, 0);
  } else {
    camera.up.set(0, 1, 0);
    camera.lookAt(0, 1.2, 0);
  }

  camera.updateProjectionMatrix();
  controls.update();
}, []);

