// config/customize/groupRoots.js
import { NODES } from "../nodes/trailerNodes";
import { TRAILER_GROUPS } from "../nodes/trailerGroups";

const rootsFromNodes = Object.fromEntries(
  Object.values(NODES).map((n) => [n.Parent, n.roots || []])
);

// fallback: if a group has no node definition, keep all meshes as "roots"
const fallbackRoots = Object.fromEntries(
  Object.entries(TRAILER_GROUPS).map(([group, meshes]) => [group, meshes])
);

export const GROUP_ROOTS = { ...fallbackRoots, ...rootsFromNodes };
