// -----------------------------------
// BUILD UI LIST (SIMPLE + STABLE)
// -----------------------------------
export function buildTrailerGroupUiList({ isE3 }) {
  const variantKey = isE3 ? "Hitch_E3" : "Hitch";
  const cfg = HITCH_VARIANTS[variantKey] || {
    chassisGroups: [],
    alwaysGroups: [],
  };

  const list = ["Hitch", "Hitch_E3", ...cfg.chassisGroups, ...cfg.alwaysGroups];
  return Array.from(new Set(list));
}

