export function sortGroupsForUi(groupIds) {
  const rank = (id) => {
    if (id === "Hitch" || id === "Hitch_E3") return -2;
    if (id === "AXLE_SELECTOR") return -3;

    if (id.startsWith("Frames_") || id.includes("Frames")) return -1;

    if (id === "13Triple_Base_E3") return GROUP_SORT_ORDER.indexOf("Floor");

if (id === "Plate_Light_Brake_Door_E4_13NCH") {
  return GROUP_SORT_ORDER.indexOf("Plate");
}
if (id === "Plate_Light_Brake_Door_E3_13NCH") {
  return GROUP_SORT_ORDER.indexOf("Plate");
}


    const matches = GROUP_SORT_ORDER.filter((k) => id.includes(k));
    if (!matches.length) return 999;

    // pick the most specific match (prevents "Inner" from capturing "InnerLights")
    const best = matches.sort((a, b) => b.length - a.length)[0];
    return GROUP_SORT_ORDER.indexOf(best);
  };

  return [...groupIds].sort((a, b) => {
    const ra = rank(a);
    const rb = rank(b);
    if (ra !== rb) return ra - rb;
    return a.localeCompare(b);
  });
}

