// src/pdf/exportTrailerPdf.js
import { jsPDF } from "jspdf";
import * as THREE from "three";


export async function exportTrailerPdf({
  title = "Trailer specification",
  specSections = [],

  setCameraView,
  setCameraMode,
  setInsideView,
    setViewSide,

  getCanvas, // () => HTMLCanvasElement
  getGl,     // () => THREE.WebGLRenderer  ✅ NEW

  fileName = "trailer-spec-and-images.pdf",
}) {
const doc = new jsPDF({ orientation: "portrait", unit: "mm", format: "a4", compress: true });


  const margin = 14;
  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  const maxW = pageW - margin * 2;

  const waitFrames = (n = 2) =>
    new Promise((resolve) => {
      let i = 0;
      const tick = () => {
        i += 1;
        if (i >= n) resolve();
        else requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
    });

  const addSpecBlock = (blockTitle, lines, startNewPage) => {
    if (startNewPage) doc.addPage();

    let y = 20;
    const ensureSpace = (needed = 8) => {
      if (y + needed > pageH - margin) {
        doc.addPage();
        y = 20;
      }
    };

    if (blockTitle) {
      doc.setFontSize(14);
      doc.text(String(blockTitle), margin, y);
      y += 8;
    }

    doc.setFontSize(10);
    (lines || []).forEach((line) => {
      const wrapped = doc.splitTextToSize(String(line), maxW);
      wrapped.forEach((w) => {
        ensureSpace(6);
        doc.text(w, margin, y);
        y += 5;
      });
    });
  };

// replace your shots array with this:
// shots: OUTSIDE + INSIDE for all views EXCEPT bottom (only outside)
const shots = [
  // Back
  { label: "Back (Outside)", view: "back", inside: false },
  { label: "Back (Inside)",  view: "back", inside: true },

  // Front
  { label: "Front (Outside)", view: "front", inside: false },
  { label: "Front (Inside)",  view: "front", inside: true },

  // Left
  { label: "Left (Outside)", view: "left", inside: false },
  { label: "Left (Inside)",  view: "left", inside: true },

  // Right
  { label: "Right (Outside)", view: "right", inside: false },
  { label: "Right (Inside)",  view: "right", inside: true },

  // Top
  { label: "Top (Outside)", view: "up", inside: false },
  { label: "Top (Inside)",  view: "up", inside: true },

  // Bottom (ONLY outside)
  { label: "Bottom (Outside)", view: "down", inside: false },
];


// and replace setPdfView with this:
const setPdfView = async ({ view, inside }) => {
  setCameraView?.(view);
  setCameraMode?.("overview");

  // inside shots: open that side
  if (inside) {
    setInsideView?.(view);        // open the wall for that view
    setViewSide?.("inside");
  } else {
    // outside shot: keep walls closed, but still use the view
    setInsideView?.(null);
    setViewSide?.("outside");
  }

  await waitFrames(3);
};



  // ✅ HIGH-RES capture with forced WHITE background + PNG
const captureHiResPng = async ({ scale = 1.6, quality = 0.72 } = {}) => {
  const gl = getGl?.();
  const canvas = getCanvas?.();
  if (!gl || !canvas) return null;

  // Save old settings
  const oldPR = gl.getPixelRatio();
  const oldClear = gl.getClearColor(new THREE.Color()).clone();
  const oldClearAlpha = gl.getClearAlpha();

  // Force WHITE background while capturing
  gl.setClearColor(0xffffff, 1);

  // Increase internal resolution
  gl.setPixelRatio(oldPR * scale);

  // Render a couple frames at new resolution
  await waitFrames(3);

  // PNG is cleaner for PDFs (and supports alpha if you later want it)
  const img = canvas.toDataURL("image/jpeg", quality);


  // Restore
  gl.setPixelRatio(oldPR);
  gl.setClearColor(oldClear, oldClearAlpha);
  await waitFrames(2);

  return img;
};


  // -------- Page 1: Title --------
  doc.setFontSize(18);
  doc.text(String(title), margin, 22);

  // -------- Spec sections --------
  specSections.forEach((sec) => addSpecBlock(sec.title, sec.lines, true));

  // -------- Screenshot pages --------
  const canvas = getCanvas?.();
  const gl = getGl?.();
  if (!canvas || !gl) {
    doc.addPage();
    doc.setFontSize(12);
    doc.text("ERROR: Canvas or WebGL renderer not found.", margin, 20);
    doc.save(fileName);
    return;
  }

  for (const s of shots) {
    doc.addPage();
    doc.setFontSize(12);
    doc.text(s.label, margin, 14);

    await setPdfView(s);

const img = await captureHiResPng({ scale: 1.6, quality: 0.72 });
if (img) doc.addImage(img, "JPEG", margin, 20, 182, 105);


  }

  doc.save(fileName);
}
