import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import * as THREE from "three";

export function useDragMove({
  scene,
  enabled,
  isPickable,
  getDragTargetName,
    preselectedAxis = null,          // "x" | "y" | "z" | null
  requireAxisPrechoice = true,      // if true, no axis => no drag

  activeId,
  onChangeActiveId,
  onHighlight,

  axes = { x: true, y: false, z: true },

  planeNormal = new THREE.Vector3(0, 1, 0),
  planeConstant = 0,

  speed = 0.15,
  dragThresholdPx = 4,

  autoLockAxis = false,
  lockPick = ["x", "z"],
  lockEpsilon = 1e-6,

  snapStepCm = 1,

  // ✅ NEW
  onDragStart,
  onDragEnd,
}) {
  const [draggingId, setDraggingId] = useState(null);

const plane = useMemo(() => {
  if (preselectedAxis === "y") {
    return new THREE.Plane(new THREE.Vector3(0, 0, 1), planeConstant);
  }
  return new THREE.Plane(new THREE.Vector3(0, 1, 0), planeConstant);
}, [preselectedAxis, planeConstant]);



  const targetRef = useRef(null);

  const startPointerLocalRef = useRef(new THREE.Vector3());
  const startTargetPosRef = useRef(new THREE.Vector3());
  const tmpWorld = useRef(new THREE.Vector3());
  const tmpLocal = useRef(new THREE.Vector3());

  const downClientRef = useRef({ x: 0, y: 0 });
  const didDragRef = useRef(false);

  const lockedAxisRef = useRef(null);

  const cmToWorld = useCallback((cm) => cm / 100, []);
  const snap = useCallback(
    (v, step) => (step > 0 ? Math.round(v / step) * step : v),
    []
  );

  const resolveTargetName = useCallback((hit) => {
    let o = hit;
    while (o && !o.name) o = o.parent;
    return o?.name || hit?.name || "";
  }, []);

  const stopDrag = useCallback(() => {
    targetRef.current = null;
    setDraggingId(null);
    didDragRef.current = false;
    lockedAxisRef.current = null;
  }, []);

  useEffect(() => {
    if (!enabled) return;
    document.body.style.cursor = draggingId ? "grabbing" : activeId ? "grab" : "default";
    return () => {
      document.body.style.cursor = "default";
    };
  }, [enabled, draggingId, activeId]);

  const pickLockedAxis = useCallback(
    (deltaVec) => {
      const candidates = lockPick.filter((ax) => axes[ax]);
      if (candidates.length <= 1) return candidates[0] || null;

      let best = null;
      let bestVal = -Infinity;
      for (const ax of candidates) {
        const v = Math.abs(deltaVec[ax] || 0);
        if (v > bestVal + lockEpsilon) {
          bestVal = v;
          best = ax;
        }
      }
      return best;
    },
    [axes, lockPick, lockEpsilon]
  );

// 🔁 REPLACE onPointerDown ENTIRELY

const onPointerDown = useCallback(
  (e) => {
    if (!enabled) return;
    e.stopPropagation();

    e.target?.setPointerCapture?.(e.pointerId);

    const hit = e.object;
    if (!hit) return;
    if (isPickable && !isPickable(hit)) return;

    downClientRef.current = { x: e.clientX, y: e.clientY };
    didDragRef.current = false;

    lockedAxisRef.current = preselectedAxis;
    if (requireAxisPrechoice && !lockedAxisRef.current) return;

    const clickedName = getDragTargetName
      ? getDragTargetName(hit)
      : resolveTargetName(hit);
    if (!clickedName) return;

    if (activeId !== clickedName) {
      onChangeActiveId?.(clickedName);
      onHighlight?.(clickedName);
    }

    const target = scene?.getObjectByName(clickedName);
    if (!target) return;

    if (!e.ray.intersectPlane(plane, tmpWorld.current)) return;

    tmpLocal.current.copy(tmpWorld.current);
    if (target.parent) target.parent.worldToLocal(tmpLocal.current);

    startPointerLocalRef.current.copy(tmpLocal.current);
    startTargetPosRef.current.copy(target.position);

    targetRef.current = target;
    setDraggingId(clickedName);

    onDragStart?.(target);
  },
  [
    enabled,
    isPickable,
    activeId,
    scene,
    plane,
    preselectedAxis,
    requireAxisPrechoice,
    resolveTargetName,
    onChangeActiveId,
    onHighlight,
    onDragStart,
  ]
);


// 🔁 REPLACE onPointerMove ENTIRELY

const onPointerMove = useCallback(
  (e) => {
    if (!enabled) return;
    const target = targetRef.current;
    if (!target) return;

    const dx = e.clientX - downClientRef.current.x;
    const dy = e.clientY - downClientRef.current.y;

    if (!didDragRef.current) {
      if (dx * dx + dy * dy < dragThresholdPx * dragThresholdPx) return;
      didDragRef.current = true;
    }

    e.stopPropagation();

    if (!e.ray.intersectPlane(plane, tmpWorld.current)) return;

    tmpLocal.current.copy(tmpWorld.current);
    if (target.parent) target.parent.worldToLocal(tmpLocal.current);

    const delta = tmpLocal.current.clone().sub(startPointerLocalRef.current);
    const ax = lockedAxisRef.current;
    if (!ax) return;

    const desired = startTargetPosRef.current.clone();
    desired[ax] += delta[ax];
    desired[ax] = snap(desired[ax], cmToWorld(snapStepCm));

    target.position.lerp(desired, Math.max(0.001, Math.min(1, speed)));
    target.updateMatrixWorld(true);
  },
  [
    enabled,
    plane,
    speed,
    dragThresholdPx,
    snap,
    cmToWorld,
    snapStepCm,
  ]
);


  const onPointerUp = useCallback(
    (e) => {
      if (!enabled) return;
      e.stopPropagation();
      e.target?.releasePointerCapture?.(e.pointerId);

      const target = targetRef.current;
      const didDrag = didDragRef.current;

      // ✅ NEW: only treat as “moved” if drag threshold was crossed
      if (target && didDrag) {
        onDragEnd?.(target);
      }

      stopDrag();
    },
    [enabled, stopDrag, onDragEnd]
  );

  const bind = enabled ? { onPointerDown, onPointerMove, onPointerUp } : {};
  return { bind, draggingId, stopDrag };
}
